        new VocabularyTerm("string-band", "String Band", ["String Bands"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["parent"] = "country", ["family"] = "country", ["dance_relevance"] = "low", ["description"] = "Early acoustic ensembles of fiddle, banjo and guitar playing old-time American dance and folk tunes. Distinguishing trait: a string-only acoustic format within the Country family, predating and feeding into Bluegrass and Old Time.", ["typical_rhythmic_feels"] = new object?[] { "Two-Beat", "Two-step", "Waltz" }, ["typical_song_forms"] = new object?[] { "AABB", "Ragtime", "Bar Form" } },
