        new VocabularyTerm("old-time", "Old Time", ["Old-Time", "Old Timey"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["parent"] = "country", ["family"] = "country", ["dance_relevance"] = "low", ["description"] = "Pre-bluegrass American rural dance music — fiddle and clawhammer banjo playing repetitive tunes for square dances. Distinguishing trait: a steady, ensemble-driven groove for dancing (no bluegrass-style solo breaks), an older Country-family style.", ["typical_rhythmic_feels"] = new object?[] { "Two-Beat", "Waltz" }, ["typical_song_forms"] = new object?[] { "AABB", "Bar Form" } },
