        new VocabularyTerm("salsa", "Salsa", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["parent"] = "latin", ["family"] = "regional", ["dance_relevance"] = "high", ["description"] = "Energetic Afro-Cuban dance music built on the clave, montuno piano and a full horn section, codified in 1970s New York. Distinguishing trait: a clave-locked, horn-driven dance form within the Latin family, faster and brighter than its son and mambo roots.", ["typical_rhythmic_feels"] = new object?[] { "Latin Clave" }, ["typical_song_forms"] = new object?[] { "Irregular" } },
            new TermDisplay("SAL", "💃", "mdi:dance-ballroom", "#607D8B")),
        new VocabularyTerm("bachata", "Bachata", ["Bachata Dominicana"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1960", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "108", "152" }, ["description"] = "Dominican guitar-based dance music descended from bolero and son, defined by a lead requinto guitar playing high, arpeggiated melodic licks over rhythm guitar, bass, bongó and the scraping güira; long stigmatized as \"música de amargue\" before Juan Luis Guerra and later Aventura/Romeo Santos carried it worldwide. Its four-beat cycle ends on a syncopated hip-accent (\"pop\") on the fourth count that the partner dance mirrors with a tap. A core street-latin social-floor genre, often shared on salsa social floors and ranging from traditional acoustic to modern sensual and urban bachata. Distinguishing trait: vs Salsa requinto-guitar lead and a closed four-count tap-on-four step, where Salsa is horn-and-piano (montuno) driven and locked to the eight-count clave.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("BAC", "🎸", "ph:guitar", "#EF6C00")),
        new VocabularyTerm("bolero", "Bolero", ["Bolero Cubano", "Cuban Bolero", "Bolero Romántico"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1885", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "80", "130" }, ["description"] = "A slow, romantic Latin-American ballad born in late-19th-century Santiago de Cuba and spread across the Hispanic world by the guitar trios romanticos and orchestral crooners. Set in 4/4 over a syncopated cinquillo-derived pulse, it foregrounds a lush, sentimental melody and lyrics of love and longing, sung over guitars or a string-and-rhythm orchestra at a languid tempo. As a slow Cuban partner-dance music it underlies the bolero social dance and the codified International and American ballroom Rumba. Distinguishing trait: vs Son Cubano, Bolero is the slow, legato, melody-and-lyric romantic ballad, where Son Cubano is up-tempo dance music driven by the son clave, an anticipated tumbao bass and a call-and-response montuno.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("BOL", "❤️", "mdi:heart", "#EF6C00")),
        new VocabularyTerm("cha-cha-cha", "Cha-Cha-Chá", ["Cha-Cha", "Cha Cha", "Chachachá", "ChaChaCha"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1953", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "100", "135" }, ["description"] = "A Cuban dance-music genre created by violinist Enrique Jorrín around 1953 as a slower, squarer offshoot of danzón-mambo, played by charanga ensembles (flute, strings, piano, güiro, timbales). Its onomatopoeic name comes from the shuffled triple-step the dancers land on the 4-and-1, marked by the güiro and a strong on-beat pulse. It anchors social Cuban/casino floors and is also a codified International Latin ballroom dance. Distinguishing trait: vs Mambo it is slower, simpler and more on-the-beat with a charanga flute-and-strings sound rather than the faster brass-driven big-band attack, and its signature triple-step replaces mambo's break-step.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("CHA", "💃", "game-icons:maracas", "#EF6C00")),
        new VocabularyTerm("kizomba", "Kizomba", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "world", ["era_start"] = "1984", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "80", "110" }, ["description"] = "An Angolan popular genre that emerged in the early 1980s, blending the local semba tradition with the smooth electronic production and rhythm of French-Caribbean zouk, sung mostly in Portuguese. It rides a slow, grounded 4/4 around 80-110 BPM with a soft, romantic groove built for the close-embrace partner dance of the same name. Its steady, unhurried pulse and warm synth-and-bass texture make it a central pillar of the street-latin social floor. Distinguishing trait: vs Zouk it keeps a slower, more grounded steady African pulse rooted in semba, where Brazilian zouk runs faster with a syncopated lambada-derived sway.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("KIZ", "🫂", "openmoji:people-hugging", "#1ABC9C")),
        new VocabularyTerm("mambo", "Mambo", ["Mambo Cubano", "Big-Band Mambo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1940", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "160", "200" }, ["description"] = "Fast, brass-driven Cuban big-band dance music that grew out of the danzón-mambo of the late 1930s and exploded into the orchestral mambo craze of the late 1940s-50s (Pérez Prado, and the New York Afro-Cuban bands of Machito and Tito Puente). It locks a horn-section riff and montuno piano vamp over the clave and a tumbao bass, with punchy syncopated brass accents and call-and-response between sections driving the floor. As the dance that established the \"on 2\" break-step timing, it is the direct forerunner of New York salsa and a foundational genre of the mambo/salsa floor. Distinguishing trait: vs Salsa it is the older big-band ancestor, brassier and more orchestral with longer instrumental riff sections, where Salsa is its tighter, song-driven 1970s codification.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("MAM", "🎺", "mdi:trumpet", "#EF6C00")),
        new VocabularyTerm("merengue", "Merengue", ["Merengue Típico", "Perico Ripiao", "Merengue Dominicano"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1850", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "120", "170" }, ["description"] = "The national dance music of the Dominican Republic — a fast, driving 2/4 march built on the tambora drum and the scraping güira, originally accordion-led (perico ripiao) and later expanded into horn-driven orquesta and big-band merengue. It carries an even, relentless two-step pulse with marcado bass and saxophone jaleo riffs, made for the simplest and most accessible of the Latin social dances. A floor staple across street-latin nights, played in sets alongside salsa and bachata. Distinguishing trait: vs Bachata it is a fast 2/4 march on tambora and güira rather than a slower 4/4 ballad led by the requinto guitar.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("MER", "🥁", "lucide:drum", "#EF6C00")),
        new VocabularyTerm("milonga", "Milonga", ["Milonga Porteña", "Milonga Ciudadana", "Milonga Argentina"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "regional", ["parent"] = "tango", ["era_start"] = "1930", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "110", "138" }, ["description"] = "The fast, playful member of the Rioplatense tango family, built on the syncopated habanera bass cell in a brisk 2/4 — earthier and more rhythmic than tango, with a teasing, ground-hugging bounce (Sebastián Piana, Francisco Canaro, Aníbal Troilo). Its double-time subdivision invites the traspié contratiempo double-steps that define the dance, and it shares the Golden-Age orquesta sound and quarter-note tempo range with its tango sibling. Note: \"milonga\" also names the tango social event itself; here it denotes the music/dance genre. Distinguishing trait: vs Tango it rides the habanera double-time 2/4 cell with a light, bouncing swing rather than the grounded marcato 4/4 walking pulse.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("MLG", "🪗", "mdi:metronome", "#607D8B")),
        new VocabularyTerm("paso-doble", "Paso Doble", ["Pasodoble", "Paso", "España Cañí"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "regional", ["era_start"] = "1920", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "112", "138" }, ["description"] = "A dramatic Spanish two-step march in brisk 2/4, rooted in military and bullfight band music and evoking the matador's cape-and-charge in the arena (the near-universal competition tune is \"España Cañí\"). Built on a steady on-beat march cadence with flamenco-tinged melodies, brass fanfares, and theatrical accents and halts that cue the dancers' poses. Distinguishing trait: vs Tango it is a straight on-beat Spanish march built around dramatic halts, not a marcato-pulse bandoneon embrace.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("PSD", "🐂", "game-icons:bull-horns", "#607D8B")),
        new VocabularyTerm("rumba-cubana", "Rumba (Cuban)", ["Rumba Cubana", "Cuban Rumba", "Guaguancó", "Yambú", "Columbia", "Rumba Guaguancó"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1880", ["dance_relevance"] = "medium", ["bpm_range"] = new object?[] { "90", "130" }, ["description"] = "Secular Afro-Cuban folkloric music from the dockside solares of Havana and Matanzas, built entirely on layered congas/cajón, claves, palitos and call-and-response vocals with no melodic instruments. Its three sub-forms drive distinct dances: the flirtatious couple guaguancó, the slow elder yambú, and the acrobatic solo male columbia. Danced socially in rumba gatherings and as the percussive root feeding casino/Afro-Cuban movement. Distinguishing trait: vs Son the rumba is pure percussion and voice over a 2-bar rumba clave with no melodic instruments, where the son adds tres/guitar, bass and a sung melody.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("RMB", "🪘", "lucide:drum", "#EF6C00")),
        new VocabularyTerm("samba", "Samba (Music)", ["Samba no Pé", "Brazilian Samba"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1916", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "96", "120" }, ["description"] = "Brazil's signature Afro-Brazilian dance music, born in early-20th-century Rio de Janeiro and inseparable from Carnival, built on a fast 2/4 pulse driven by a surdo-and-tamborim percussion battery with a strong \"two\" and busy sixteenth-note syncopation. The buoyant, bouncing groove carries social samba no pé and partnered samba de gafieira on the street-latin floor and underpins the codified International Latin ballroom samba. Vocal and pandeiro-led variants (pagode, partido alto) and the percussion-only batucada all share its swinging, springy momentum. Distinguishing trait: vs Bossa Nova it is a fast, full-throttle percussion-driven dance groove rather than bossa's hushed, slow whispered-guitar comp drawn from the same samba root.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("SMB", "🥁", "lucide:drum", "#EF6C00")),
        new VocabularyTerm("son-cubano", "Son Cubano", ["Cuban Son", "Son Montuno"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "latin", ["era_start"] = "1900", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "140", "180" }, ["description"] = "The foundational Afro-Cuban genre from eastern Cuba's Oriente, built on the son clave, the tres guitar's syncopated guajeo, and a two-part form that opens with a sung verse and breaks into an open call-and-response montuno over anticipated tumbao bass and bongó/clave percussion (Trío Matamoros, Sexteto Habanero, Arsenio Rodríguez, later Buena Vista Social Club). It is the trunk from which mambo, cha-cha-chá, and salsa all grew, and it remains a living social-floor music in the casino/salsa world, danced grounded on the contratiempo. Distinguishing trait: vs Salsa, son is the slower, sparser, tres-led acoustic root, where salsa is its faster, brighter, horn-section-driven New York codification of the same clave-and-montuno lineage.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("SON", "🪘", "qlementine-icons:bongos-24", "#EF6C00")),
        new VocabularyTerm("vals", "Vals", ["Tango Vals", "Tango Waltz", "Vals Criollo", "Vals Cruzado"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["family"] = "regional", ["parent"] = "tango", ["era_start"] = "1900", ["dance_relevance"] = "high", ["bpm_range"] = new object?[] { "150", "240" }, ["description"] = "The Rioplatense tango waltz — a 3/4 tango-family form (vals criollo) played by the same Golden-Age orquestas as tango and milonga, with a continuously flowing, circular lilt felt one-per-bar over a strong beat 1. It is one of the three core tanda types spun at every milonga, ranging from lyrical Fresedo/De Angelis valses to fast, driving D'Arienzo/Biagi readings. Dancers cross-step and turn on the accented beats, gliding around the bar rather than marking each beat. Distinguishing trait: vs Tango it is in 3/4 felt one-per-bar with a rotary, sweeping flow, where tango is a marcato 4/4 with sharp staccato accents and walked steps.", ["source"] = "SDTS scene-completeness rework (2026-06): the dance-scene genre its scene's dances are danced to, absent from the swing/blues-seeded catalog. Researched + adversarially verified via multi-agent workflow." },
            new TermDisplay("VLS", "🎻", "mdi:metronome", "#607D8B")),
        new VocabularyTerm("zouk", "Brazilian Zouk", ["Zouk", "Lambada-Zouk", "Zouk-Lambada"], false,
