            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "bass-line", ["dsl_key"] = "BoogieShuffle", ["pulse"] = "4", ["subdivision"] = "straight", ["accent"] = "on-beat", ["tier"] = "1", ["bpm_range"] = new object?[] { "120", "200" }, ["description"] = "The piano left hand (or bass) drives eight even straight 8th notes per bar ('8 to the bar') as a rolling motor, the signature of boogie-woogie. Distinguishing trait: despite its name it is straight, not triplet like Shuffle, and uses eight notes per bar rather than the four of Walking 4.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/boogie-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=BYrcZp7Pdh8", ["youtube_label"] = "Pine Top Smith — Pine Top's Boogie Woogie" } },
            new TermDisplay("BGE", "🎹", "mdi:piano", "#00838F")),
        new VocabularyTerm("slow-drag", "Slow Drag", ["Slow Blues Shuffle", "Slow Blues"], false,
