            new TermDisplay("BKB", "🥁", "lucide:drum", "#00838F")),
        new VocabularyTerm("straight-4", "Straight 4", ["Straight 4/4", "Four-on-the-floor", "Electronic 4-on-the-floor"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "straight", ["dsl_key"] = "Straight4", ["pulse"] = "4", ["subdivision"] = "straight", ["accent"] = "on-beat", ["tier"] = "1", ["bpm_range"] = new object?[] { "60", "300" }, ["description"] = "Even, non-swung 8th notes over a 4-beat pulse, with no triplet feel, common in bebop, cool/modal jazz and Latin jazz. Distinguishing trait: vs Jazz Swing 8ths, the 8ths are all equal length (a metronomic 'da-da-da-da' rather than the swung 'ne-ke-den').", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/straight-4.mp3", ["youtube"] = "https://www.youtube.com/watch?v=ylXk1LBvIqU", ["youtube_label"] = "Miles Davis — So What" } },
            new TermDisplay("STG", "⬛", "mdi:square-wave", "#00838F")),
        new VocabularyTerm("waltz", "Waltz", ["3/4", "Slow Waltz"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "waltz", ["dsl_key"] = "Waltz", ["pulse"] = "3", ["subdivision"] = "straight", ["accent"] = "on-beat", ["tier"] = "1", ["bpm_range"] = new object?[] { "80", "200" }, ["description"] = "A 3-beats-per-bar pulse ('ONE-two-three') with a strong downbeat, drawn from European ballroom tradition and adopted into jazz from the 1950s onward. Distinguishing trait: its unmistakable triple meter (not 4 or 2 beats) makes it rarely confused with any other feel.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/waltz.mp3", ["youtube"] = "https://www.youtube.com/watch?v=lbjZPFBD6JU", ["youtube_label"] = "Norah Jones — Come Away With Me" } },
            new TermDisplay("WLZ", "💃", "mdi:dance-ballroom", "#00838F")),
        new VocabularyTerm("two-beat", "Two-Beat", ["Two Beat", "2-Beat", "2 Beat", "Cut Time", "Cut-Time", "Alla Breve", "Early Swing", "Ragtime Two-Beat", "Ragtime syncopation"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "bass-line", ["dsl_key"] = "TwoBeat", ["pulse"] = "2", ["subdivision"] = "bass-feel", ["accent"] = "on-beat", ["tier"] = "1", ["bpm_range"] = new object?[] { "120", "240" }, ["description"] = "A pre-swing 'oom-pah' feel that stresses beats 1 and 3 in 4/4, with the bass on the roots and banjo/guitar on the afterbeats, characteristic of Dixieland, ragtime and New Orleans hot jazz. Distinguishing trait: vs Jazz Swing 8ths it is bouncier, more duple and less legato (1927 Armstrong Hot Five vs 1937 Goodman big band).", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/two-beat.mp3", ["youtube"] = "https://www.youtube.com/watch?v=65SBsF28dnc", ["youtube_label"] = "Louis Armstrong and His Hot Seven — Potato Head Blues" } },
            new TermDisplay("2BT", "✂️", "mdi:scissors", "#00838F")),
        new VocabularyTerm("latin-clave", "Latin Clave", ["Clave", "Son Clave", "Rumba Clave", "Latin", "Mambo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "latin", ["dsl_key"] = "LatinClave", ["pulse"] = "4", ["subdivision"] = "straight", ["accent"] = "clave", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "220" }, ["description"] = "An Afro-Cuban 5-note rhythmic pattern spanning a 2-bar cycle (son/rumba clave) that organizes the whole band, the foundation of son, salsa, mambo and Latin jazz. Distinguishing trait: vs Habanera it is a 20th-century cross-bar accent pattern rather than a per-bar bass figure, and it is Cuban 4/4 rather than Brazilian (Bossa Nova).", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/latin-clave.mp3", ["youtube"] = "https://www.youtube.com/watch?v=BpAXzTpANNw", ["youtube_label"] = "Tito Puente — Oye Como Va" } },
            new TermDisplay("CLV", "🪘", "mingcute:drum-fill", "#00838F")),
        new VocabularyTerm("habanera", "Habanera", ["Tango Habanera"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "latin", ["dsl_key"] = "Habanera", ["pulse"] = "2", ["subdivision"] = "straight", ["accent"] = "clave", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "140" }, ["description"] = "A 19th-century Cuban bass figure (dotted-8th + 16th + 8th + 8th) repeating in a 2-beat frame, the 'Spanish tinge' that fed early New Orleans jazz, blues and Argentine tango. Distinguishing trait: vs Latin Clave it is a per-bar bass pattern rather than clave's 5-note cross-bar accent pattern.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/habanera.mp3", ["youtube"] = "https://www.youtube.com/watch?v=K7BE7trV_oQ", ["youtube_label"] = "Maria Callas — Habanera, Bizet's Carmen" } },
            new TermDisplay("HAB", "🌹", "lucide:rose", "#00838F")),
        new VocabularyTerm("bossa-nova", "Bossa Nova", ["Bossa", "Brazilian"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "brazilian", ["dsl_key"] = "BossaNova", ["pulse"] = "2", ["subdivision"] = "straight", ["accent"] = "clave", ["tier"] = "2", ["bpm_range"] = new object?[] { "100", "160" }, ["description"] = "A Brazilian feel derived from samba crossed with cool jazz: a syncopated guitar chord pattern over a steady, quiet bass in a flowing 2/4 pulse. Distinguishing trait: vs Latin Clave it is Brazilian 2/4 (not Cuban 4/4), and vs Straight 4 it is 2-pulse with an identifying bossa guitar comp.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/bossa-nova.mp3", ["youtube"] = "https://www.youtube.com/watch?v=s61-e29Vr6Q", ["youtube_label"] = "Stan Getz feat. Astrud Gilberto — The Girl from Ipanema" } },
            new TermDisplay("BSA", "🏖️", "mdi:beach", "#00838F")),
        new VocabularyTerm("second-line", "Second Line", ["NOLA Second Line", "Second-Line"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "march", ["dsl_key"] = "SecondLine", ["pulse"] = "4", ["subdivision"] = "straight", ["accent"] = "backbeat", ["tier"] = "3", ["bpm_range"] = new object?[] { "100", "160" }, ["description"] = "The specific New Orleans brass-band parade/procession drum feel: kick on 1 and 3 with a syncopated street-beat snare and dominant bass drum, played by a brass ensemble. Distinguishing trait: vs Cut Time it is the genre-specific NO variant identified by sousaphone/tuba bass, brass-band instrumentation and the syncopated snare.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/second-line.mp3", ["youtube"] = "https://www.youtube.com/watch?v=iDaneKADnZw", ["youtube_label"] = "Rebirth Brass Band — When the Saints Go Marching In" } },
            new TermDisplay("2LN", "🎺", "mdi:trumpet", "#00838F")),
        new VocabularyTerm("two-step", "Two-step", ["Country Two-Step", "Two Step"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "bass-line", ["dsl_key"] = "TwoStep", ["pulse"] = "4", ["subdivision"] = "straight", ["accent"] = "on-beat", ["tier"] = "3", ["bpm_range"] = new object?[] { "120", "180" }, ["description"] = "A country/western feel with a walking bass on all four beats and straight 8ths, the predictable groove of Bob Wills-era western swing. Distinguishing trait: musically close to Walking 4 but set apart by its country context and instrumentation (fiddle, steel guitar, country vocals) rather than jazz.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/two-step.mp3", ["youtube"] = "https://www.youtube.com/watch?v=dxDacEgmMpo", ["youtube_label"] = "Bob Wills & His Texas Playboys — Take Me Back to Tulsa" } },
            new TermDisplay("2ST", "🤠", "ph:cowboy-hat", "#00838F")),
        new VocabularyTerm("jump-shuffle", "Jump Shuffle", ["Jump-Blues Shuffle"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "JumpShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "1", ["bpm_range"] = new object?[] { "120", "200" }, ["description"] = "An uptempo, driving shuffle with an emphasized backbeat and punchy horn riffs, the bridge feel of jump blues and early R&B (Louis Jordan, Big Joe Turner). Distinguishing trait: vs plain Shuffle it is the faster, horn-driven variant, and vs Boogie Shuffle it rides a walking bass and horn hooks rather than a boogie-woogie bass pattern.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/jump-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=PR6pHtiNT_k", ["youtube_label"] = "Louis Jordan — Caldonia" } },
            new TermDisplay("JMP", "⚡", "mdi:flash", "#00838F")),
        new VocabularyTerm("manouche-swing", "Manouche Swing", ["Pompé", "Gypsy Swing", "Django Swing"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "swing", ["dsl_key"] = "ManoucheSwing", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "140", "280" }, ["description"] = "The gypsy-jazz 'la pompe' rhythm-guitar technique: two or more rhythm guitars strum all four beats with an alternating down-up chop to create nonstop drive without drums. Distinguishing trait: vs Jazz Swing 8ths it is a specific rhythm-guitar technique (rather than the melodic swing of soloists) and carries a subtle swing bias absent from a perfectly even Straight 4.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/manouche-swing.mp3", ["youtube"] = "https://www.youtube.com/watch?v=uTlo809EIlo", ["youtube_label"] = "Django Reinhardt — Minor Swing" } },
            new TermDisplay("MAN", "🎸", "ph:guitar", "#00838F")),
        new VocabularyTerm("chicago-shuffle", "Chicago Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "ChicagoShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "140" }, ["description"] = "A medium-tempo electric-blues shuffle with triplet 8ths and a hard backbeat, the band-tight ensemble groove of post-war Chicago blues (Muddy Waters, Little Walter). Distinguishing trait: vs the generic Shuffle it is the amplified, full-band Chicago variant; vs Jump Shuffle it sits slower and is guitar/harmonica-led rather than horn-driven.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/chicago-shuffle.mp3", ["youtube"] = "https://www.youtube.com/results?search_query=Little%20Walter%20My%20Babe", ["youtube_label"] = "Little Walter — My Babe" } },
            new TermDisplay("CHI", "🏙️", "mdi:city", "#00838F")),
        new VocabularyTerm("nola-shuffle", "NOLA Shuffle", ["New Orleans Shuffle"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "NolaShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "90", "140" }, ["description"] = "A New Orleans shuffle with triplet 8ths and a backbeat, carrying a loose, syncopated street-parade lilt rooted in the city's piano-and-drums tradition (Professor Longhair, Fats Domino). Distinguishing trait: vs Chicago Shuffle it swings looser and more rolling, and vs Second Line it is a band shuffle rather than the brass-band parade beat.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/nola-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=ox5eCN_V9mQ", ["youtube_label"] = "Fats Domino — I'm Walkin'" } },
            new TermDisplay("NLA", "⚜️", "mdi:fleur-de-lis", "#00838F")),
        new VocabularyTerm("soul-shuffle", "Soul Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "SoulShuffle", ["pulse"] = "4", ["subdivision"] = "mixed", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "130" }, ["description"] = "A shuffle with a mixed straight/triplet feel and a firm backbeat, blending a soul/R&B horn-and-organ sensibility into the groove (1960s-70s soul). Distinguishing trait: vs Blues Shuffle it carries a smoother soul phrasing and its subdivision is mixed rather than strictly triplet, and vs R&B Shuffle it leans warmer and more polished.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/soul-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=T_uSM-i_c_I", ["youtube_label"] = "Wilson Pickett — Mustang Sally" } },
            new TermDisplay("SOU", "💜", "mdi:heart", "#00838F")),
        new VocabularyTerm("retro-soul-shuffle", "Retro Soul Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "RetroSoulShuffle", ["pulse"] = "4", ["subdivision"] = "mixed", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "130" }, ["description"] = "A modern revival of the soul shuffle with a mixed straight/triplet feel and backbeat, recorded to evoke vintage 1960s soul (Daptone-style retro-soul, Sharon Jones, Amy Winehouse). Distinguishing trait: musically near-identical to Soul Shuffle but flagged as a contemporary throwback recording rather than a period-original.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/retro-soul-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=HoqSO0hAjZw", ["youtube_label"] = "Amy Winehouse — Rehab" } },
            new TermDisplay("RSO", "📻", "mdi:radio", "#00838F")),
        new VocabularyTerm("rock-shuffle", "Rock Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "RockShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "100", "160" }, ["description"] = "An uptempo triplet shuffle with a heavy backbeat driven by electric guitar and a rock band, the blues-rock shuffle of acts like ZZ Top and Stevie Ray Vaughan. Distinguishing trait: vs Blues Shuffle it is harder and more amplified with a rock attack, and vs Jump Shuffle it is guitar-driven rather than horn-driven.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/rock-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=I3MTGhRC82s", ["youtube_label"] = "Stevie Ray Vaughan & Double Trouble — Pride and Joy" } },
            new TermDisplay("RCK", "🤘", "mdi:guitar-electric", "#00838F")),
        new VocabularyTerm("rb-shuffle", "R&B Shuffle", ["Rhythm & Blues Shuffle"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "RBShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "90", "140" }, ["description"] = "A triplet shuffle with a strong backbeat in the classic rhythm-and-blues mold, vocal-forward with horns and a danceable mid-tempo bounce. Distinguishing trait: vs Jump Shuffle it is slower and less frantic, and vs Soul Shuffle it stays strictly triplet rather than mixed.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/rb-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=6uTDa3771HM", ["youtube_label"] = "Ray Charles — What'd I Say" } },
            new TermDisplay("RNB", "🎙️", "mdi:microphone", "#00838F")),
        new VocabularyTerm("blues-shuffle", "Blues Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "BluesShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "80", "140" }, ["description"] = "The unmarked mid-tempo triplet shuffle with a backbeat that underpins most twelve-bar blues, the default blues-dance shuffle feel. Distinguishing trait: vs the parent Shuffle it is explicitly blues-scoped rather than the jump/Chicago archetype, and vs the regional variants (Chicago, Delta, Piedmont, NOLA, Swamp) it carries no specific scene, so use it when no regional flavor is identified.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/blues-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=u8AIFxp1euM", ["youtube_label"] = "B.B. King — Everyday I Have the Blues (Live at the Regal, 1964)" } },
            new TermDisplay("BLS", "💙", "tdesign:guitar", "#00838F")),
        new VocabularyTerm("piedmont-shuffle", "Piedmont Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "PiedmontShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "3", ["bpm_range"] = new object?[] { "80", "140" }, ["description"] = "A triplet shuffle with a backbeat tied to the East Coast Piedmont blues tradition, built around fingerpicked acoustic guitar with an alternating-bass ragtime lilt (Blind Boy Fuller, Rev. Gary Davis). Distinguishing trait: vs Delta Shuffle it is brighter and more syncopated with a ragtime bounce rather than a heavy, dragging groove.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/piedmont-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=M2oIWyr4v7U", ["youtube_label"] = "Blind Boy Fuller — Step It Up and Go (1940)" } },
            new TermDisplay("PMT", "🏔️", "mdi:mountain", "#00838F")),
        new VocabularyTerm("delta-shuffle", "Delta Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "DeltaShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "3", ["bpm_range"] = new object?[] { "80", "140" }, ["description"] = "A triplet shuffle with a backbeat in the Mississippi Delta acoustic-blues tradition, raw and often loosely metered around a droning slide or fingerpicked guitar (Son House, Robert Johnson lineage). Distinguishing trait: vs Piedmont Shuffle it is darker and heavier with less ragtime syncopation, and rougher than the band-tight Chicago Shuffle.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/delta-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=Ug0ZRSbmCRM", ["youtube_label"] = "Robert Johnson — Sweet Home Chicago (1936)" } },
            new TermDisplay("DLT", "🛶", "mdi:water", "#00838F")),
        new VocabularyTerm("western-swing-shuffle", "Western Swing Shuffle", ["Western Shuffle"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "WesternSwingShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "2", ["bpm_range"] = new object?[] { "100", "180" }, ["description"] = "An uptempo triplet shuffle with a backbeat from the western-swing tradition, swung jazz feel played on fiddle and steel guitar with a country accent (Bob Wills and the Texas Playboys). Distinguishing trait: vs Jump Shuffle it carries country/western instrumentation rather than horns, and vs the Two-step it is a swung shuffle rather than straight 8ths.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/western-swing-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=dxDacEgmMpo", ["youtube_label"] = "Bob Wills & the Texas Playboys — Take Me Back to Tulsa" } },
            new TermDisplay("WSW", "🐎", "mdi:violin", "#00838F")),
        new VocabularyTerm("swamp-shuffle", "Swamp Shuffle", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "shuffle", ["dsl_key"] = "SwampShuffle", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "backbeat", ["tier"] = "3", ["bpm_range"] = new object?[] { "60", "120" }, ["description"] = "A slow, greasy triplet shuffle with a backbeat from the Louisiana swamp-blues tradition, sparse and laid-back with a heavy lazy pocket (Slim Harpo, Lightnin' Slim). Distinguishing trait: vs Blues Shuffle it sits slower and dirtier with a dragging swamp feel, and vs NOLA Shuffle it is rural and minimal rather than parade-influenced.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/swamp-shuffle.mp3", ["youtube"] = "https://www.youtube.com/watch?v=-5x7NIqga8M", ["youtube_label"] = "Slim Harpo — Baby Scratch My Back" } },
            new TermDisplay("SWP", "🐊", "mdi:snake", "#00838F")),
        new VocabularyTerm("nola-rhumba", "NOLA Rhumba", ["Rhumba Boogie", "New Orleans Rhumba"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "latin", ["dsl_key"] = "NolaRhumba", ["pulse"] = "4", ["subdivision"] = "mixed", ["accent"] = "clave", ["tier"] = "3", ["bpm_range"] = new object?[] { "90", "160" }, ["description"] = "A New Orleans groove with a mixed feel built over a clave/habanera-derived accent, the 'rhumba-boogie' that grafts a Latin tinge onto a rolling NO beat (Professor Longhair). Distinguishing trait: vs Latin Clave it is a New Orleans piano-blues feel using the clave as a flavor rather than a true Afro-Cuban band pattern, and vs NOLA Shuffle it rides a Latin accent instead of a straight shuffle.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/nola-rhumba.mp3", ["youtube"] = "https://www.youtube.com/watch?v=5IILlTLqBOY", ["youtube_label"] = "Professor Longhair — Tipitina" } },
            new TermDisplay("NRH", "🥥", "lucide-lab:coconut", "#00838F")),
        new VocabularyTerm("bebop", "Bebop", ["Be-Bop"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "swing", ["dsl_key"] = "Bebop", ["pulse"] = "4", ["subdivision"] = "triplet", ["accent"] = "off-beat", ["tier"] = "2", ["bpm_range"] = new object?[] { "140", "280" }, ["description"] = "A fast swung-triplet feel with off-beat accents and a light ride-cymbal pulse, the agile small-group jazz feel of 1940s bebop (Charlie Parker, Dizzy Gillespie). Distinguishing trait: vs Jazz Swing 8ths it runs faster and more virtuosic with sharper off-beat phrasing, and vs Hard Bop Swing it is lighter and less blues/gospel-inflected.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/bebop.mp3", ["youtube"] = "https://www.youtube.com/watch?v=BUHwR-khV20", ["youtube_label"] = "Charlie Parker — Ornithology (1946)" } },
            new TermDisplay("BOP", "💫", "mdi:music-note-eighth", "#00838F")),
        new VocabularyTerm("hard-bop", "Hard Bop Swing", ["Hard Bop"], false,
