            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "tango", ["pulse"] = "2", ["subdivision"] = "straight", ["accent"] = "off-beat", ["description"] = "The playful syncopated milonga with traspié (contratiempo double-steps) over the habanera frame. Distinguishing trait: vs Habanera it adds the off-beat contratiempo lift rather than riding the plain bass cell.", ["source"] = "SDTS scene-completeness rework (2026-06): rhythm feel the scene's dances are danced to, absent from the swing/blues-seeded catalog.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/milonga-traspie.mp3" } },
