            new TermDisplay("TSC", "🪗", "mdi:metronome", "#00838F")),
        new VocabularyTerm("tango-vals", "Tango Vals", ["Vals Cruzado"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["cluster"] = "tango", ["pulse"] = "3", ["subdivision"] = "straight", ["accent"] = "on-beat", ["description"] = "A continuously-flowing 3/4 tango-waltz lilt felt one-per-bar with a strong beat 1, tied to Golden-Age valses. Distinguishing trait: vs the Waltz it is faster and more circular, stepping on accented beats across the bar rather than a square ONE-two-three.", ["source"] = "SDTS scene-completeness rework (2026-06): rhythm feel the scene's dances are danced to, absent from the swing/blues-seeded catalog.", ["audio"] = new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["clip"] = "rhythmic_feel/tango-vals.mp3" } },
