    private static Dimension BuildInstrumentation() => new(DimensionIds.Instrumentation, "core",
    [
        new VocabularyTerm("solo-piano", "Solo Piano", ["Piano Solo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "solo", ["typical_genres"] = new object?[] { "Ragtime", "Stride Piano", "Boogie Woogie" }, ["description"] = "A single pianist covering every role from one instrument: the left hand is the rhythm section (bass plus chords), the right hand carries melody and improvisation, spanning composed ragtime, improvised stride, and driving boogie-woogie. Distinguished by the left-hand style (ragtime oom-pah march, stride's wide bass-to-chord leaps, boogie's relentless eight-to-the-bar ostinato)." },
            new TermDisplay("SoP", "🎹", "mdi:piano", "#546E7A")),
        new VocabularyTerm("solo-blues-performer", "Solo Blues Performer", ["Solo Blues", "Solo Blues Singer", "Solo Blues Guitar"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "solo", ["typical_genres"] = new object?[] { "Delta Blues", "Country Blues", "Piedmont Blues" }, ["description"] = "One person with a guitar and voice (often open-tuning slide/bottleneck plus a moaning, growling vocal) — the most intimate form of blues, with no band and no production. Distinguished by its non-metronomic, breathing 'human' rhythm and slide guitar that imitates the voice; unlike Vocal + Piano, the single performer plays and sings simultaneously rather than being two musicians." },
            new TermDisplay("SoB", "🎸", "mdi:guitar-acoustic", "#546E7A")),
        new VocabularyTerm("solo", "Solo", ["Solo Performer"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "solo", ["typical_genres"] = new object?[] { }, ["description"] = "A single performer of any kind — the generic catch-all when one musician carries the whole track but the instrument is unspecified or not piano/guitar. Distinguishing trait: use this only when the more specific Solo Piano or Solo Blues Performer does not apply; it asserts ensemble size of one without naming the instrument." },
            new TermDisplay("SOL", "👤", "lucide:mic-vocal", "#546E7A")),
        new VocabularyTerm("vocal-piano", "Vocal + Piano", ["Vocal and Piano", "Voice and Piano", "Vocal Piano Duo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "duo", ["typical_genres"] = new object?[] { "Classic Vaudeville Blues", "Vocal Jazz", "Cabaret" }, ["description"] = "One singer plus one pianist — the smallest ensemble that still gives the vocal full harmonic and rhythmic support, with the piano covering bass, chords, fills, and solos so the singer has expressive freedom. Distinguished by maximum intimacy and a sparse palette where every word and keystroke is audible; unlike Solo Blues Performer it is two distinct musicians, and unlike Jazz Trio it has no bass or drums." },
            new TermDisplay("VoP", "🎤", "mdi:piano", "#546E7A")),
        new VocabularyTerm("duo-generic", "Duo", ["Duet Ensemble"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "duo", ["typical_genres"] = new object?[] { }, ["description"] = "Any two-musician pairing — the generic two-piece when the specific instrument combination is unspecified or does not fit Vocal + Piano or Blues Duo. Distinguishing trait: use this only when the more specific duo values do not apply; it asserts an ensemble of two without naming the instruments or idiom." },
            new TermDisplay("Duo", "👥", "mdi:account-multiple", "#546E7A")),
        new VocabularyTerm("blues-duo", "Blues Duo", ["Blues Duet"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "duo", ["typical_genres"] = new object?[] { "Blues", "Country Blues" }, ["description"] = "Two musicians playing blues, typically a guitarist and a second guitar, harmonica, or voice in the country-blues tradition. Distinguishing trait: larger than the lone Solo Blues Performer (two distinct players) but smaller than the rhythm-section Blues Band, with an acoustic, intimate feel and no drums." },
            new TermDisplay("BlD", "🎶", "mdi:guitar-acoustic", "#546E7A")),
        new VocabularyTerm("jazz-trio", "Jazz Trio", ["Piano Trio", "Trio"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "trio", ["typical_genres"] = new object?[] { "Vocal Jazz", "Soul Jazz", "Cool Jazz" }, ["description"] = "Piano plus double bass plus drums — the most intimate jazz ensemble that still carries a rhythm section, serving either as backing for a vocalist or as a standalone group. Distinguished by the 'air' and space that a big band cannot offer, supporting a soloist or singer without competing with the voice." },
            new TermDisplay("JzT", "🎼", "mdi:piano", "#546E7A")),
        new VocabularyTerm("rockabilly-trio", "Rockabilly Trio", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "trio", ["typical_genres"] = new object?[] { "Rockabilly", "Early Rock 'n' Roll" }, ["description"] = "Guitar plus slap bass plus drums (often drumless) — the minimal lineup that defined the Sun Records rockabilly sound, raw and garage-like with slapback echo making a small group sound big. Distinguished by the slap bass that is simultaneously bass and percussion, and frequently absent or minimal drums." },
            new TermDisplay("RbT", "🤠", "mdi:guitar-electric", "#546E7A")),
        new VocabularyTerm("jazz-combo", "Jazz Combo", ["Jazz Group", "Small Jazz Combo", "Jazz Quartet", "Jazz Quintet", "Jazz Sextet", "Modern Swing Combo", "Small Swing Combo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Hot Jazz", "Jump Blues", "Bebop", "Cool Jazz", "Hard Bop", "Modal Jazz", "Soul Jazz", "Modern Swing Revival" }, ["description"] = "A small jazz group from trio to octet, most commonly a quintet (trumpet, sax, piano, bass, drums), using the same lineup across hot jazz, bebop, and hard bop where the difference is playing style rather than instrumentation. Distinguished by improvisational freedom and intimate interplay, more open and unpredictable than scored big band arrangements." },
            new TermDisplay("JzC", "🎷", "mdi:saxophone", "#546E7A")),
        new VocabularyTerm("blues-band", "Blues Band", ["Electric Blues Band", "Chicago Blues Band"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Chicago Blues", "Blues" }, ["description"] = "Electric guitar plus amplified harmonica plus rhythm section — the Chicago Blues sound born when Delta players electrified to cut through loud urban bars. Distinguished by a steady, danceable shuffle groove (drums and bass keep the tempo in the pocket) that retains blues rawness, a compromise between authenticity and danceability that solo Delta blues lacks." },
            new TermDisplay("BlB", "⚡", "mdi:guitar-electric", "#546E7A")),
        new VocabularyTerm("manouche-ensemble", "Manouche", ["Manouche Ensemble", "Gypsy Jazz Ensemble", "Manouche Group", "Gypsy Jazz"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Gypsy Jazz" }, ["description"] = "Acoustic guitars plus violin plus double bass with no drums and no horns — the all-string Hot Club format Django Reinhardt created, where rhythm comes entirely from 'la pompe' rhythm guitar and walking bass. Distinguished by being a unique all-acoustic lineup found in no other jazz genre, with the percussive 'la pompe' standing in for drums." },
            new TermDisplay("Man", "🌹", "mdi:guitar-acoustic", "#546E7A")),
        new VocabularyTerm("string-band", "String Band", ["Country String Band", "Hillbilly Band"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Country", "Old Time", "Western Swing" }, ["description"] = "Fiddle plus guitar plus banjo plus double bass — the original all-acoustic country lineup from rural American home music-making, rooted in Irish/Scottish (fiddle) and African (banjo) traditions. Distinguished by a warm, organic, homemade folk sound where fiddle and banjo create the recognizable country character." },
            new TermDisplay("StB", "🪕", "dinkie-icons:banjo", "#546E7A")),
        new VocabularyTerm("new-orleans-small-group", "New Orleans Small Group", ["NOLA Small Group", "New Orleans Combo", "NOLA Combo", "Rhythm Kings"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "New Orleans Jazz", "Hot Jazz", "Dixieland" }, ["description"] = "A small hot-jazz combo (front-line trumpet, clarinet, trombone over a rhythm section) playing the New Orleans/Dixieland repertoire in a club setting rather than the street — the seated, recording-band equivalent of the brass band (New Orleans Rhythm Kings, early Armstrong sides). Distinguishing trait: smaller and tighter than the marching New Orleans Brass Band, with a fixed seated rhythm section rather than portable tuba-and-banjo, while keeping the same collective front-line improvisation." },
            new TermDisplay("NOG", "🎺", "mdi:trumpet", "#546E7A")),
        new VocabularyTerm("rockabilly-combo", "Rockabilly Combo", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Rockabilly", "Early Rock 'n' Roll" }, ["description"] = "A 4-6 piece rockabilly band that expands the classic trio with extra instruments such as a separate lead guitar, sax, piano, and a full drum kit. Distinguished from the Rockabilly Trio by being more layered and fuller rather than the raw, minimal three-piece Sun Records sound." },
            new TermDisplay("RbC", "🕺", "ph:cowboy-hat", "#546E7A")),
        new VocabularyTerm("jump-blues-combo", "Jump Blues Combo", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Jump Blues", "Rhythm & Blues" }, ["description"] = "A 5-7 piece sax-led R&B/jump format of the 1940s-50s (Louis Jordan's Tympany Five archetype) with tight rhythm, lead sax, vocal, and horn riffs, bridging big band swing and early R&B/rock'n'roll. Distinguished by sax-led dominance in the jump-blues idiom; unlike the later R&B Combo it sits in the 1940s-55 era with heavier sax focus." },
            new TermDisplay("JBC", "💥", "mdi:saxophone", "#546E7A")),
        new VocabularyTerm("rb-combo", "R&B Combo", ["R&B Combo with Piano"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Rhythm & Blues" }, ["description"] = "A 4-6 piece pre-soul R&B band of the 1950s-65 era with a mixed lead instrument (guitar, piano, or sax) and vocal-led repertoire, bridging the sax-led Jump Blues Combo and the horn-driven Soul Combo. Distinguished by its mixed lead and R&B repertoire of that era; unlike Soul Combo it predates the horn-section-dominant gospel-vocal soul sound." },
            new TermDisplay("RnB", "🎵", "mdi:piano", "#546E7A")),
        new VocabularyTerm("soul-combo", "Soul Combo", ["Retro Soul Combo", "Motown Combo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Soul", "Southern Soul" }, ["description"] = "A 4-7 piece soul band of the 1965-and-later era (Stax/Atlantic/Motown lineage) with a tight rhythm section, horn section, and gospel-derived expressive vocal. Distinguished from the R&B Combo by a more prominent horn section and gospel-rooted vocal expressiveness." },
            new TermDisplay("SoC", "❤️", "mdi:microphone-variant", "#546E7A")),
        new VocabularyTerm("rock-combo", "Rock Combo", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Rock", "Classic Rock" }, ["description"] = "The post-1965 standard rock band format invented in the Beatles era: lead vocal plus two guitars plus bass plus drums. Distinguished from the Rockabilly Combo by being modern (post-1965) without slap bass and twang guitar; rarely used in a swing context." },
            new TermDisplay("RkC", "🤘", "mdi:guitar-electric", "#546E7A")),
        new VocabularyTerm("new-orleans-brass-band", "New Orleans Brass Band", ["NOLA Brass Band", "Brass Band"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "medium", ["typical_genres"] = new object?[] { "New Orleans Jazz", "Dixieland", "Trad Jazz" }, ["description"] = "A street wind ensemble — the roots of jazz — where three front-line horns (cornet/trumpet, clarinet, trombone) collectively improvise over a portable rhythm section of tuba, banjo, and marching drums. Distinguished by three-voice collective polyphony ('organized chaos') in which no one solos in the modern sense, and a recognizable syncopated second-line rhythm." },
            new TermDisplay("NOB", "🎺", "mdi:trumpet", "#546E7A")),
        new VocabularyTerm("dixieland-ensemble", "Dixieland", ["Dixieland Ensemble", "Dixieland Band", "Dixieland Combo"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "medium", ["typical_genres"] = new object?[] { "Dixieland", "Trad Jazz" }, ["description"] = "A traditional-jazz band built on collective front-line polyphony (cornet/trumpet, clarinet, trombone) over a banjo/piano/bass/drums rhythm section, playing the 1920s trad and revival repertoire. Distinguishing trait: closely overlaps the New Orleans Small Group but names the revival/trad-jazz idiom and lineup broadly; unlike a Jazz Combo it favors collective ensemble polyphony over sequential individual solos." },
            new TermDisplay("Dix", "🎺", "mdi:trumpet", "#546E7A")),
        new VocabularyTerm("soul-blues-band", "Soul Blues Band", ["Soul Blues Combo", "R&B Band"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "medium", ["typical_genres"] = new object?[] { "Soul Blues", "Rhythm & Blues" }, ["description"] = "Front-and-center vocal plus horn section plus rhythm section — a more produced sound than the Blues Band, pairing a gospel-trained voice with a polished rhythmic engine and 'glamorous' horns (Memphis Stax/Hi style). Distinguished by the vocal as protagonist (not the guitar) and the polish of horns and organ, making it the most accessible blues for a wide audience." },
            new TermDisplay("SBB", "🔥", "mdi:microphone-variant", "#546E7A")),
        new VocabularyTerm("western-swing-band", "Western Swing Band", [], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "medium", ["typical_genres"] = new object?[] { "Western Swing" }, ["description"] = "Country instruments (fiddle, steel guitar) playing swing jazz — a unique fusion found in no other genre, with the lineup expanding from 5 to 18+ players and jazz elements (sax, trumpet) added on top. Distinguished by jazz sophistication and improvisation in a country form, with steel guitar tone and fiddle jazz solos that no jazz big band has, setting it apart from pure country." },
            new TermDisplay("WSB", "🐎", "ph:cowboy-hat", "#546E7A")),
        new VocabularyTerm("big-band-ensemble", "Big Band", ["Big Band Ensemble", "Swing Big Band", "Modern Big Band", "Big Band Revival", "Latin Jazz Big Band"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "large", ["typical_genres"] = new object?[] { "Swing", "Big Band", "Kansas City Jazz", "Neo-Swing", "Latin Jazz" }, ["description"] = "A large ensemble organized into sections (saxes, trumpets, trombones, rhythm) that trade and answer each other — the sound that defined the swing era and created the music for Lindy Hop, built on Fletcher Henderson's arranging template. Distinguished by a 'wall of sound' and huge dynamic range (whisper to full-ensemble shout chorus) that no smaller group can reproduce." },
            new TermDisplay("BB", "🎺", "mdi:trumpet", "#546E7A")),
        new VocabularyTerm("orchestra", "Orchestra", ["String Orchestra", "Symphony Orchestra"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "large", ["typical_genres"] = new object?[] { "Vocal Jazz", "Easy Listening", "Adult Standards" }, ["description"] = "A large ensemble built around a string section, often with woodwinds, brass, and a rhythm section behind a singer — the lush studio backing of vocal-jazz, easy-listening, and pop-standards sessions (Sinatra-with-strings, Nelson Riddle arrangements). Distinguishing trait: led by bowed strings rather than the sax/trumpet/trombone sections that define a Big Band, producing a sweeping, smooth backdrop rather than a swinging, sectional shout." },
            new TermDisplay("Orc", "🎻", "mdi:violin", "#546E7A")),
        new VocabularyTerm("vocal-acapella-group", "Vocal Acapella", ["Vocal Acapella Group", "Vocal Quartet", "Acapella", "Vocal Ensemble (Acapella)"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Doo-wop", "Vocal Jazz", "Gospel" }, ["description"] = "A vocal-only ensemble of 3-6 voices with no instrumental accompaniment (occasionally percussion or hand-claps), where the voices are the entire instrumentation in lead-plus-harmony arrangements. Distinguished from a combo-with-vocals by having only voices, and from Vocal + Piano by being three or more voices with no piano." },
            new TermDisplay("Aca", "🎙️", "mdi:account-group", "#546E7A")),
        new VocabularyTerm("electronic-swing", "Electronic Swing", ["Electronic with Swing Samples", "Electroswing Production", "Swing Samples"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["size"] = "small", ["typical_genres"] = new object?[] { "Electro Swing" }, ["description"] = "A DAW-produced format (one or two producers) combining programmed beats, synthesized bass, and sampled vintage big band brass and vocals — not an acoustic ensemble but a production. Distinguished from every acoustic instrumentation category by being studio production-based rather than a live ensemble." },
            new TermDisplay("ElS", "🎛️", "lucide:turntable", "#546E7A"))
    ],
    grouping: new TermGrouping("size", [new("solo", "Solo"), new("duo", "Duo"), new("trio", "Trio"), new("small", "Small group"), new("medium", "Medium group"), new("large", "Large group")]));

    private static Dimension BuildInstrument() => new(DimensionIds.Instrument, "core",
    [
        new VocabularyTerm("piano", "Piano", ["Piano Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = null, ["typical_examples"] = new object?[] { "Count Basie", "Fats Waller", "Jerry Lee Lewis", "Oscar Peterson" }, ["description"] = "Piano carries the melody and harmonic drive of the track, from stride and boogie left-hand pumps to single-note bop lines. Distinguishing trait: a polyphonic keyboard lead that holds rhythm and chords at once, unlike the single-line reed or brass leads. Count Basie and Fats Waller are the swing-era touchstones." },
            new TermDisplay("p", "🎹", "mdi:piano", "#6D4C41")),
        new VocabularyTerm("clarinet", "Clarinet", ["Clarinet Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "reed", ["typical_examples"] = new object?[] { "Benny Goodman", "Artie Shaw", "Pete Fountain" }, ["description"] = "Clarinet leads with a fluid, woody upper-register voice that soars over the band, the signature solo instrument of the swing era. Distinguishing trait: brighter and more agile than the saxophone, its reed sibling, with a liquid legato Goodman and Shaw made famous on uptempo swing." },
            new TermDisplay("cl", "🎶", "game-icons:clarinet", "#6D4C41")),
        new VocabularyTerm("saxophone", "Saxophone", ["Saxophone Led", "Sax Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "reed", ["typical_examples"] = new object?[] { "Coleman Hawkins", "Charlie Parker", "Lester Young", "Stan Getz" }, ["description"] = "Saxophone leads with a warm, breathy reed tone, from Hawkins' big tenor to Parker's fast alto lines. Distinguishing trait: rounder and heavier than the clarinet, its reed sibling, and the backbone of any sax-section feature. Lester Young and Stan Getz mark the lighter, cooler end." },
            new TermDisplay("sax", "🎷", "mdi:saxophone", "#6D4C41")),
        new VocabularyTerm("trumpet", "Trumpet", ["Trumpet Led", "Cornet", "Cornet Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "brass", ["typical_examples"] = new object?[] { "Louis Armstrong", "Harry James", "Dizzy Gillespie", "Miles Davis" }, ["description"] = "Trumpet (or cornet) leads with a bright, piercing brass voice that cuts through the band, equally at home on hot-jazz breaks and bop. Distinguishing trait: higher and more brilliant than the trombone, its brass sibling. Louis Armstrong is the foundational example; Dizzy Gillespie and Miles Davis carry it into bop and beyond." },
            new TermDisplay("tp", "🎺", "mdi:trumpet", "#6D4C41")),
        new VocabularyTerm("trombone", "Trombone", ["Trombone Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "brass", ["typical_examples"] = new object?[] { "Jack Teagarden", "Tommy Dorsey", "J.J. Johnson" }, ["description"] = "Trombone leads with a smooth, sliding brass voice in the lower-middle register, capable of growls, glissandos, and singing ballads. Distinguishing trait: warmer and deeper than the trumpet, its brass sibling. Jack Teagarden and Tommy Dorsey define the swing-era lead." },
            new TermDisplay("tb", "📯", "game-icons:trombone", "#6D4C41")),
        new VocabularyTerm("guitar", "Guitar", ["Guitar Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "string", ["typical_examples"] = new object?[] { "Charlie Christian", "T-Bone Walker", "Chuck Berry", "Django Reinhardt" }, ["description"] = "Guitar takes the lead line, from acoustic Gypsy-swing runs to amplified single-string solos. Distinguishing trait: a plucked string lead with sharper attack than the bowed violin, its string sibling. Charlie Christian pioneered the electric jazz solo; Django Reinhardt defines the acoustic Manouche lead." },
            new TermDisplay("g", "🎸", "ph:guitar", "#6D4C41")),
        new VocabularyTerm("violin", "Violin", ["Violin Led", "Fiddle", "Fiddle Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "string", ["typical_examples"] = new object?[] { "Stéphane Grappelli", "Joe Venuti", "Bob Wills (fiddle)" }, ["description"] = "Violin (or fiddle) leads with a singing, bowed string voice, swinging in Gypsy jazz and sawing in Western Swing. Distinguishing trait: a sustained, bowed lead with continuous tone, unlike the plucked attack of the guitar or banjo. Stéphane Grappelli is the jazz touchstone; Bob Wills the Western-Swing one." },
            new TermDisplay("vln", "🎻", "mdi:violin", "#6D4C41")),
        new VocabularyTerm("banjo", "Banjo", ["Banjo Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "string", ["typical_examples"] = new object?[] { "Johnny St. Cyr (Hot Five)", "Eddie Condon", "Harry Reser", "Earl Scruggs" }, ["description"] = "Banjo leads with a bright, percussive, fast-decaying string tone central to early hot jazz and trad bands. Distinguishing trait: sharper and more clipped than the sustaining guitar, its string sibling, giving an older-sounding chank. Johnny St. Cyr of the Hot Five and Eddie Condon are the classic examples." },
            new TermDisplay("bjo", "🪕", "game-icons:banjo", "#6D4C41")),
        new VocabularyTerm("harmonica", "Harmonica", ["Harmonica Led", "Harp", "Harp Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "novelty", ["typical_examples"] = new object?[] { "Little Walter", "Sonny Boy Williamson", "Junior Wells" }, ["description"] = "Harmonica (harp) leads with a reedy, vocal, bent-note voice, most at home in blues. Distinguishing trait: a free-reed lead with expressive pitch-bending unlike any of the brass or string instruments. Little Walter and Sonny Boy Williamson are the amplified-blues benchmarks." },
            new TermDisplay("hrm", "🎼", "qlementine-icons:harmonica-16", "#6D4C41")),
        new VocabularyTerm("organ", "Organ", ["Organ Led", "Hammond", "Hammond Led", "Hammond B-3"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "novelty", ["typical_examples"] = new object?[] { "Jimmy Smith", "Jack McDuff", "Brother Jack McDuff" }, ["description"] = "Organ leads with the sustained, drawbar-rich voice of the Hammond B-3, often grooving over its own bass pedals in soul-jazz and jump blues. Distinguishing trait: a held, swelling keyboard tone with no decay, unlike the percussive attack of the piano. Jimmy Smith and Jack McDuff are the touchstones." },
            new TermDisplay("org", "🎵", "game-icons:pipe-organ", "#6D4C41")),
        new VocabularyTerm("vibraphone", "Vibraphone", ["Vibraphone Led", "Vibes", "Vibes Led", "Vibes-led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "novelty", ["typical_examples"] = new object?[] { "Lionel Hampton", "Milt Jackson", "Gary Burton" }, ["description"] = "Vibraphone (vibes) leads with a shimmering, metallic, mallet-struck tone, often with a slow tremolo. Distinguishing trait: a tuned-percussion lead with a bell-like sustain unlike the brass, reed, or string voices. Lionel Hampton brought it into swing; Milt Jackson into bop." },
            new TermDisplay("vib", "🔔", "game-icons:xylophone", "#6D4C41")),
        new VocabularyTerm("accordion", "Accordion", ["Accordion Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "novelty", ["typical_examples"] = new object?[] { "Clifton Chenier", "Richard Galliano", "Astor Piazzolla" }, ["description"] = "Accordion leads with a reedy, bellows-driven voice that can sustain and swell, prominent in zydeco, musette, and tango. Distinguishing trait: a free-reed lead capable of chords and held tones unlike the single-line harmonica. Clifton Chenier (zydeco) and Astor Piazzolla (tango) mark the range." },
            new TermDisplay("acc", "🪗", "game-icons:accordion", "#6D4C41")),
        new VocabularyTerm("drums", "Drums", ["Drums Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "rhythm", ["typical_examples"] = new object?[] { "Gene Krupa", "Buddy Rich", "Art Blakey" }, ["description"] = "Drums take the lead through extended kit features, solos, and tom-tom hooks rather than just keeping time. Distinguishing trait: an unpitched percussion lead, the rhythmic counterpart to the pitched bass within the rhythm family. Gene Krupa and Buddy Rich are the swing-era showcases." },
            new TermDisplay("dr", "🥁", "nimbus:drums", "#6D4C41")),
        new VocabularyTerm("bass", "Bass", ["Bass Led", "Bass Guitar", "Double Bass"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "rhythm", ["typical_examples"] = new object?[] { "Jimmy Blanton", "Paul Chambers", "Charles Mingus", "Jaco Pastorius" }, ["description"] = "Bass takes the lead through walking features, solos, and prominent bass lines, on double bass or bass guitar. Distinguishing trait: the pitched low-end lead of the rhythm family, paired with the unpitched drums. Jimmy Blanton pioneered the solo role; Paul Chambers and Mingus carried it into bop." },
            new TermDisplay("b", "🎸", "game-icons:guitar-bass-head", "#6D4C41")),
        new VocabularyTerm("reed", "Reed", ["Reed Led", "Reeds", "Reeds Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Big band sax section", "Miller 'In the Mood' sax chase" }, ["description"] = "Generic family covering clarinet- and saxophone-led tracks, including reed-section features. Distinguishing trait: use when the lead is clearly a reed voice or a sax/clarinet section, but the specific instrument is unknown or shifts across the track. A Miller-style sax chase or big-band sax section is the typical case." },
            new TermDisplay("Rd", "🎷", "mdi:saxophone", "#6D4C41")),
        new VocabularyTerm("brass", "Brass", ["Brass Led", "Horns", "Horns Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Ellington brass features", "big band brass shouts" }, ["description"] = "Generic family covering trumpet- and trombone-led tracks, including brass-section shouts and features. Distinguishing trait: use when the lead is clearly brass or a horn section, but the specific instrument is unknown or alternates. Ellington brass features and big-band brass shouts are the typical case." },
            new TermDisplay("Br", "🎺", "mdi:trumpet", "#6D4C41")),
        new VocabularyTerm("string", "String", ["String Led", "Strings", "Strings Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Manouche ensemble (Django + Grappelli)", "Western Swing fiddle+steel" }, ["description"] = "Generic family covering guitar-, violin-, and banjo-led tracks. Distinguishing trait: use when the lead is a plucked or bowed string ensemble, or alternates among strings, rather than one identifiable instrument. A Manouche ensemble (Django plus Grappelli) or a Western-Swing fiddle-and-steel front line is the typical case." },
            new TermDisplay("Str", "🎻", "ph:guitar", "#6D4C41")),
        new VocabularyTerm("vocal", "Vocal", ["Vocal Led", "Vocals Led", "Voice Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Ella", "Sinatra", "Bessie", "Mahalia" }, ["description"] = "Generic family for vocal-led tracks where the voice is the lead instrument. Distinguishing trait: covers no specific sub-instruments; use whenever a singer fronts the track, across jazz, blues, and gospel. Ella, Sinatra, Bessie Smith, and Mahalia Jackson span the range." },
            new TermDisplay("Voc", "🎤", "mdi:microphone", "#6D4C41")),
        new VocabularyTerm("rhythm", "Rhythm", ["Rhythm Led", "Rhythm Section"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Gene Krupa drum features", "walking bass focus", "Krupa-led tom-tom hooks" }, ["description"] = "Generic family covering drums- and bass-led tracks where the rhythm section is the feature. Distinguishing trait: use when the lead is the rhythm section as a whole, or shifts between drums and bass, rather than a melodic instrument. Gene Krupa drum features and walking-bass focus are the typical cases." },
            new TermDisplay("Rhy", "🥁", "mdi:metronome", "#6D4C41")),
        new VocabularyTerm("novelty", "Novelty", ["Novelty Led"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "generic", ["typical_examples"] = new object?[] { "Clifton Chenier (accordion)", "Clarence Cameron White (banjo)", "vibes-features" }, ["description"] = "Generic catch-all family for less-common lead instruments: harmonica, organ, vibraphone, accordion, and banjo. Distinguishing trait: use when the lead falls outside the main reed, brass, string, and rhythm families. Clifton Chenier on accordion or a vibes feature is the typical case." },
            new TermDisplay("Nov", "✨", "tabler:sparkle", "#6D4C41")),
        new VocabularyTerm("tuba", "Tuba", ["Sousaphone", "Bass Horn"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "brass", ["lead_capable"] = "false", ["typical_examples"] = new object?[] { "Howard Johnson", "New Orleans brass bands" }, ["description"] = "Tuba (or sousaphone) supplies the walking bass line in a brass band or early-jazz rhythm section. Distinguishing trait: the lowest brass voice, a section/credit instrument that rarely takes the lead." },
            new TermDisplay("tba", "🎺", "game-icons:tuba", "#6D4C41")),
        new VocabularyTerm("cello", "Cello", ["Violoncello"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "string", ["lead_capable"] = "false", ["typical_examples"] = new object?[] { "Oscar Pettiford (cello)", "Ron Carter (piccolo cello)" }, ["description"] = "Cello adds a warm low-string voice, occasionally bowed or plucked as a solo colour but usually a section/credit instrument. Distinguishing trait: lower and darker than the violin, its string sibling." },
            new TermDisplay("vc", "🎻", "game-icons:cello", "#6D4C41")),
        new VocabularyTerm("flute", "Flute", ["Flutes"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "novelty", ["lead_capable"] = "false", ["typical_examples"] = new object?[] { "Frank Wess", "Herbie Mann" }, ["description"] = "Flute contributes a light, airy woodwind colour, most often a section or credit voice in swing and blues rather than the lead. Distinguishing trait: a breathy, high woodwind unlike the reed or brass leads." },
            new TermDisplay("fl", "🎶", "game-icons:flute", "#6D4C41")),
        new VocabularyTerm("washboard", "Washboard", ["Frottoir"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "rhythm", ["lead_capable"] = "false", ["typical_examples"] = new object?[] { "Washboard Sam", "jug-band rhythm sections" }, ["description"] = "Washboard provides scraped hand-percussion in jug bands and early hot jazz. Distinguishing trait: an unpitched credit/rhythm instrument, the folk cousin of the drum kit." },
            new TermDisplay("wb", "🥁", "game-icons:washboard", "#6D4C41")),
        new VocabularyTerm("percussion", "Percussion", ["Percussions"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tier"] = "specific", ["parent"] = "rhythm", ["lead_capable"] = "false", ["typical_examples"] = new object?[] { "Latin percussion sections", "congas, bongos, timbales" }, ["description"] = "Percussion covers hand and auxiliary percussion (congas, bongos, timbales, shakers) beyond the drum kit. Distinguishing trait: an unpitched credit/rhythm voice added for texture, not a lead." },
            new TermDisplay("perc", "🥁", "game-icons:congas", "#6D4C41"))
    ]);

    private static Dimension BuildRecordingContext() => new(DimensionIds.RecordingContext, "core",
    [
        new VocabularyTerm("studio", "Studio", ["Studio Recording", "Studio Session"], false,
