    private static Dimension BuildSongForm() => new(DimensionIds.SongForm, "core",
    [
        new VocabularyTerm("blues12-bar", "12-bar Blues", ["Blues12", "12 Bar Blues", "Blues 12", "Twelve-bar Blues"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Blues12", ["bars"] = "12", ["pattern"] = "A4+A4+B4", ["meter"] = "4/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Blues", "Jump Blues", "Boogie Woogie", "Rhythm & Blues", "Rockabilly" }, ["typical_share"] = "0.3", ["description"] = "A 12-bar blues chorus built on a I-IV-V progression, split into three 4-bar phrases following an A-A'-B (statement, varied repeat, answer) pattern that repeats throughout the song. By far the most common form in blues, jump blues, boogie woogie and R&B; distinguished from other blues forms purely by its 12-bar length (vs 8, 16 or 24)." },
            new TermDisplay("B12", "🎺", "mdi:format-list-numbered", "#455A64")),
        new VocabularyTerm("bar-form", "Bar Form", ["Stollen-Stollen-Abgesang", "VVC", "Verse-Verse-Chorus", "AAB Section Form"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "AAB", ["bars"] = null, ["pattern"] = "Verse + Verse + Chorus (at the section level)", ["meter"] = "4/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Folk", "Country", "Rockabilly" }, ["description"] = "A section-level AAB structure (Stollen-Stollen-Abgesang): two similar verses followed by a contrasting closing chorus, the whole pattern often repeating across the song. Unlike 12-bar Blues, the AAB here operates at the section level (verse + verse + chorus, 16+ bars each) rather than the bar level. Its roots are medieval German Meistersang, and it shapes many Lutheran hymns and the Prize Song in Wagner's Die Meistersinger." },
            new TermDisplay("AAB", "📜", "mdi:scroll", "#455A64")),
        new VocabularyTerm("aaba32-bar", "AABA", ["32-bar AABA", "32 Bar AABA", "Standard AABA"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "AABA", ["bars"] = "32", ["pattern"] = "A8+A8+B8+A8", ["meter"] = "4/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Swing", "Big Band", "Vocal Jazz", "Gypsy Jazz" }, ["typical_share"] = "0.4", ["description"] = "The classic Tin Pan Alley / Great American Songbook form: 32 bars in four 8-bar sections (A-A-B-A), where the B 'bridge' contrasts harmonically and melodically and the final A recapitulates the opening. The defining trait is that the fourth section returns to the first; if it does not, it is ABAC instead." },
            new TermDisplay("AABA", "🎼", "mdi:vector-square", "#455A64")),
        new VocabularyTerm("abac32-bar", "ABAC", ["32-bar ABAC", "32 Bar ABAC"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "ABAC", ["bars"] = "32", ["pattern"] = "A8+B8+A8+C8", ["meter"] = "4/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Vocal Jazz", "Adult Standards" }, ["typical_share"] = "0.15", ["description"] = "A 32-bar form in four 8-bar sections (A-B-A-C) where, unlike AABA, the final section (C) introduces new material rather than recapitulating the opening A. The primary distinguishing cue: after the second A, the melody does NOT return but resolves with something new. It is common among standards written for Hollywood films." },
            new TermDisplay("ABAC", "🎶", "lucide:shapes", "#455A64")),
        new VocabularyTerm("double16-32-bar", "Double 16", ["32-bar Double16", "32 Bar Double16", "AB Double16", "Double16"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Double16", ["bars"] = "32", ["pattern"] = "A16+B16", ["meter"] = "4/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Vocal Jazz", "Adult Standards" }, ["typical_share"] = "0.05", ["description"] = "A 32-bar form built as two equal 16-bar sections (A16+B16) with no internal 8-bar subdivisions; the melodic phrase runs a full 16 bars without repeating, giving a 'long-flow' feel. It is the most ambiguous 32-bar form, since many standards (e.g. 'All of Me') can equally be heard as AABA or ABAC at the 8-bar level." },
            new TermDisplay("D16", "🪞", "mdi:mirror", "#455A64")),
        new VocabularyTerm("ragtime-multistrain", "Ragtime", ["Multi-strain Ragtime", "Multi-strain", "Ragtime Multi-strain"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Ragtime", ["bars"] = "64", ["pattern"] = "AABBACCDD or AABBCCDD", ["meter"] = "2/4", ["tier"] = "1", ["typical_genres"] = new object?[] { "Ragtime", "Hot Jazz", "Stride Piano", "Dixieland" }, ["typical_share"] = "0.05", ["description"] = "A multi-strain march-derived form with several distinct 16-bar themes ('strains'), typically AABBACCDD or AABBCCDD, often with an intro and transition bridges and a 'trio' strain modulating to the subdominant. Distinguished from cyclic forms by the fact that the melody keeps moving to brand-new strains instead of returning (and from a medley, since it is one composition)." },
            new TermDisplay("RAG", "🎹", "mdi:piano", "#455A64")),
        new VocabularyTerm("blues8-bar", "8-bar Blues", ["Blues8", "8 Bar Blues", "Blues 8"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Blues8", ["bars"] = "8", ["pattern"] = "I-V-IV-I", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Blues", "Country Blues", "Delta Blues" }, ["description"] = "A compressed 8-bar blues that keeps the I-IV-V harmonic basis of 12-bar blues in just 8 bars, common in early country/Delta blues. Distinguished from 12-bar Blues purely by its shorter 8-bar chorus that comes back around noticeably faster." },
            new TermDisplay("B8", "🎸", "mingcute:guitar-line", "#455A64")),
        new VocabularyTerm("blues16-bar", "16-bar Blues", ["Blues16", "16 Bar Blues", "Blues 16", "Major Blues 16"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Blues16", ["bars"] = "16", ["pattern"] = "AAAB or extended 12-bar", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Blues" }, ["description"] = "An extended major-key blues of 16 bars, usually heard as a 12-bar progression with an added 4-bar section or as an AAAB structure (three repeats plus an answer). Distinguished from 12-bar Blues by its longer chorus, and from 16-bar AB by its blues (I-IV-V) harmony rather than a folk A8+B8." },
            new TermDisplay("B16", "🎵", "mdi:music-note", "#455A64")),
        new VocabularyTerm("blues16-minor", "16-bar Minor Blues", ["Blues16Minor", "Minor Blues 16", "16-bar Minor"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Blues16Minor", ["bars"] = "16", ["pattern"] = "i-iv-V7", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Gypsy Jazz" }, ["description"] = "A 16-bar form in a minor key using an i-iv-V7 cycle, most iconic in gypsy jazz / manouche (Django Reinhardt's 'Minor Swing' is the prototype), often in four 4-bar sections. The minor key (i-iv-V7) is the key distinguisher from the major-key 16-bar Blues (I-IV-V)." },
            new TermDisplay("B16m", "🌑", "mdi:ghost", "#455A64")),
        new VocabularyTerm("ab16-bar", "AB", ["16-bar AB", "16 Bar AB", "AB 16"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "AB", ["bars"] = "16", ["pattern"] = "A8+B8", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Folk" }, ["description"] = "A short 16-bar form of two contrasting 8-bar sections (A8+B8) with no recapitulation, common in folk, hymns and children's songs but rare in jazz. Critically, it must NOT be confused with 32-bar Double16: this is the short A8+B8 form, not the long A16+B16." },
            new TermDisplay("AB", "🔁", "mingcute:repeat-line", "#455A64")),
        new VocabularyTerm("aabb32-bar", "AABB", ["32-bar AABB", "32 Bar AABB"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "AABB", ["bars"] = "32", ["pattern"] = "A8+A8+B8+B8", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Folk" }, ["description"] = "A 32-bar double-strain form (A8+A8+B8+B8): two themes, each repeated, with no bridge or recapitulation, rooted in marching-band, folk, Celtic and western-swing traditions. Distinguished from AABA by the absence of a contrasting bridge/return — the last section is the repeated B, not a return to A." },
            new TermDisplay("AABB", "🥁", "lucide:drum", "#455A64")),
        new VocabularyTerm("rhythm-changes", "Rhythm Changes", ["Rhythm Changes 32", "I Got Rhythm"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "RhythmChanges", ["bars"] = "32", ["pattern"] = "AABA with Gershwin harmony", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Swing", "Bebop" }, ["description"] = "A variant of 32-bar AABA fixed to the harmony of Gershwin's 'I Got Rhythm' (I-vi-ii-V turnarounds in the A sections, a cycle-of-fifths bridge), used by the bebop era as the basis for countless contrafacts. Structurally identical to AABA, it is identified by that specific harmony rather than by its shape; when unsure, tag plain AABA." },
            new TermDisplay("RC", "🌀", "mdi:metronome", "#455A64")),
        new VocabularyTerm("aaba-with-verse", "AABA with Verse", ["AABAWithVerse", "AABA + Verse", "AABA w/ Verse"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "AABAWithVerse", ["bars"] = "48", ["pattern"] = "16 verse + 32 AABA chorus", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Adult Standards", "Vocal Jazz" }, ["description"] = "An older Tin Pan Alley convention: a 16-bar narrative 'introductory verse' (often rubato, played only once) preceding a standard 32-bar AABA refrain, for roughly 48 bars total. Distinguished from plain AABA by that one-time sectional verse — not the repeating verse of modern pop, and not a mere band intro." },
            new TermDisplay("AABAv", "🎤", "mdi:microphone", "#455A64")),
        new VocabularyTerm("blues-with-verse", "Blues with Verse", ["BluesWithVerse", "Blues + Verse", "Verse Blues"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "BluesWithVerse", ["bars"] = "28", ["pattern"] = "16 verse + 12 AAB blues chorus", ["meter"] = "4/4", ["tier"] = "2", ["typical_genres"] = new object?[] { "Classic Vaudeville Blues" }, ["description"] = "A compound race-records form: a 16-bar introductory verse played once, followed by a repeating 12-bar AAB blues chorus (roughly 28 bars across the opening). It is the blues analogue of AABA-with-Verse, distinguished from plain 12-bar Blues by the one-time verse and from AABA-with-Verse by its 12-bar blues refrain." },
            new TermDisplay("BvV", "🗣️", "mingcute:speech-line", "#455A64")),
        new VocabularyTerm("blues24-bar", "24-bar Blues", ["Blues24", "24 Bar Blues", "Blues 24"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Blues24", ["bars"] = "24", ["pattern"] = "extended 12-bar", ["meter"] = "4/4", ["tier"] = "3", ["typical_genres"] = new object?[] { "Blues" }, ["description"] = "A rare, largely theoretical extended blues of 24 bars, understood either as a doubled/expanded 12-bar cycle (bebop-style, with secondary dominants) or as two 12-bar choruses joined into one macro-chorus. Distinguished from 12-bar Blues by a chorus cycle that returns roughly twice as slowly; nearly absent from real-world repertoire." },
            new TermDisplay("B24", "📏", "mdi:ruler", "#455A64")),
        new VocabularyTerm("abcd32-bar", "ABCD", ["32-bar ABCD", "Through-composed 32"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "ABCD", ["bars"] = "32", ["pattern"] = "A8+B8+C8+D8", ["meter"] = "4/4", ["tier"] = "3", ["typical_genres"] = new object?[] { "Jazz" }, ["description"] = "A through-composed 32-bar form of four distinct, non-repeating 8-bar sections (A-B-C-D), often modulating without returning to the home key. Distinguished from AABA/ABAC by the fact that all four sections sound different with no recapitulation; genuinely rare, as most apparent ABCD songs are really ABAC." },
            new TermDisplay("ABCD", "🔤", "bi:alphabet", "#455A64")),
        new VocabularyTerm("irregular", "Irregular", ["Non-standard", "Custom Form", "Through-composed"], false,
            new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["dsl_key"] = "Irregular", ["bars"] = "0", ["pattern"] = "varies", ["meter"] = "varies", ["tier"] = "3", ["typical_genres"] = new object?[] { "Experimental" }, ["description"] = "A sentinel catch-all for songs that fit no standard pattern — odd chorus lengths (28, 36, 40 bars), through-composed structures, or odd meters like 5/4, 7/4 and 9/8 (e.g. 'Take Five', 'Blue Rondo a la Turk'). Use only after ruling out miscounting, extended variants of standard forms, compound forms and medleys; bars=0 means 'variable', not literally zero." },
            new TermDisplay("IRR", "🌊", "mdi:sine-wave", "#455A64"))
    ]);

