            new VocabularyTerm("swing", "Swing", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["description"] = "The umbrella for the swing-descended partner and solo dances: the swing-era dances (Lindy Hop, Balboa, the Shags, East Coast Swing, Jive, Boogie Woogie, Solo Jazz, Charleston, Electro Swing) and the swing-descended West Coast Swing and Carolina Shag. A group value, not a dance with its own steps: tag it when a track suits swing dancing in general without singling out one dance." },
                new TermDisplay("SWG", "🎷", "mdi:account-group", "#F6E1C9")),
