                new TermDisplay("LH", "🤸", "game-icons:high-kick", "#E6433B")),
            new VocabularyTerm("balboa", "Balboa", ["BLB", "Slow Bal", "SBL"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "swing-partner", ["parent"] = "swing", ["tempo_min"] = "180", ["tempo_max"] = "300", ["typical_genres"] = new object?[] { "Big Band", "Swing", "Gypsy Jazz" }, ["description"] = "A close-embrace swing dance from 1930s Southern California for fast tempos, where the feet stay minimal and shuffling while the rhythm is expressed through the body. Its distinguishing trait is subtle, near-invisible footwork that works in crowds and at speeds where Lindy Hop becomes exhausting (vs Collegiate Shag, which solves fast tempos with energetic vertical hopping instead)." },
                new TermDisplay("BAL", "👞", "mdi:shoe-heel", "#E68A2E")),
            new VocabularyTerm("collegiate-shag", "Collegiate Shag", [], false,
