                new TermDisplay("CSH", "🦵", "material-symbols:footprint", "#E8C547")),
            new VocabularyTerm("st-louis-shag", "St. Louis Shag", ["St Louis Shag", "STLS"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "swing-partner", ["parent"] = "swing", ["tempo_min"] = "200", ["tempo_max"] = "300", ["typical_genres"] = new object?[] { "Swing" }, ["description"] = "A stationary, very fast 8-count partner dance from St. Louis, danced side-by-side with strong stomping footwork. Its distinguishing trait is staying in place (no travel across the floor) at extreme tempos of 200-300 BPM (vs Collegiate Shag, which hops and travels)." },
                new TermDisplay("SLS", "🌉", "material-symbols:footprint", "#8FBF3F")),
            new VocabularyTerm("east-coast-swing", "East Coast Swing", [], true,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "swing-partner", ["parent"] = "swing", ["tempo_min"] = "130", ["tempo_max"] = "180", ["typical_genres"] = new object?[] { "Swing", "Big Band", "Jump Blues" }, ["replaced_by"] = "boogie-woogie-dance", ["description"] = "A simplified, codified version of Lindy Hop standardized by Arthur Murray dance schools in the 1940s for mass teaching, using a 6-count rock-step/triple-step/triple-step pattern. Distinguished by being more upright, structured and predictable with far less improvisation and bounce than its Lindy Hop parent, and a narrower tempo range (~130-180 BPM)." },
                new TermDisplay("ECS", "🔄", "mdi:dance-ballroom", "#3FB984")),
            new VocabularyTerm("jive", "Jive", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "swing-partner", ["parent"] = "swing", ["tempo_min"] = "150", ["tempo_max"] = "210", ["typical_genres"] = new object?[] { "Jump Blues", "Early Rock 'n' Roll", "Rockabilly" }, ["description"] = "The competitive ballroom version of swing, one of the five International Latin dances, derived from Lindy Hop/East Coast Swing but codified for competition. Distinguished by pronounced kicks and flicks and a showy, athletic 'pumping' knee action aimed at impressing judges and spectators." },
                new TermDisplay("JV", "⚡", "mdi:flash", "#3FA7D6")),
            new VocabularyTerm("boogie-woogie-dance", "Boogie Woogie", ["Boogie", "Boogie Woogie Dance"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "boogie-rocknroll", ["parent"] = "swing", ["tempo_min"] = "130", ["tempo_max"] = "200", ["typical_genres"] = new object?[] { "Boogie Woogie", "Jump Blues", "Early Rock 'n' Roll", "Rockabilly" }, ["description"] = "An energetic partner dance set to boogie woogie, rock'n'roll and rockabilly, with a strong European competitive scene (WRRC). Distinguished from Lindy Hop by its linear (rather than circular) figures and a driving, bass-following bounce, plus kicks/flicks and a more codified competitive technique." },
                new TermDisplay("BW", "🎹", "mdi:piano", "#4666C4")),
            new VocabularyTerm("solo-jazz", "Solo Jazz", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "solo-rhythmic", ["parent"] = "swing", ["tempo_min"] = "120", ["tempo_max"] = "220", ["typical_genres"] = new object?[] { "Swing", "Big Band" }, ["description"] = "Improvised solo jazz dance (also called authentic or vernacular jazz) with no partner, performed in jam circles, performances and group routines on swing/jazz music. Distinguished by classic vernacular steps (Suzy Q, Shorty George) and codified group routines like the Shim Sham, plus body isolations and polyrhythmic personal expression rather than any fixed basic." },
                new TermDisplay("SJ", "🕺", "mdi:human-female-dance", "#7E57C2")),
            new VocabularyTerm("charleston", "Charleston", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "solo-rhythmic", ["parent"] = "swing", ["tempo_min"] = "140", ["tempo_max"] = "240", ["typical_genres"] = new object?[] { "Hot Jazz", "Stride Piano", "Dixieland" }, ["description"] = "The iconic 1920s dance recognizable by 'kicked-back' steps with knees together, feet swiveling out, and swinging kicks front and back; exists in solo and partner forms and is built into Lindy Hop as core technique. Its distinguishing trait is the swivel-and-kick footwork, split into '20s Charleston' (straight rhythm) and 'Swing Charleston' (swung feel, embedded in Lindy Hop)." },
                new TermDisplay("CH", "🦶", "mdi:shoe-print", "#C44FA0")),
            new VocabularyTerm("tap-dance", "Tap Dance", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "solo-rhythmic", ["tempo_min"] = "80", ["tempo_max"] = "220", ["typical_genres"] = new object?[] { "Swing", "Big Band", "Ragtime" }, ["description"] = "A rhythmic dance where metal plates on the toe and heel turn the foot into a percussion instrument, fusing African polyrhythm with Irish step-dance footwork. Distinguished by the dancer being simultaneously dancer and percussionist, improvising like a jazz musician and 'trading fours' with the band as the 'fourth instrument'." },
                new TermDisplay("TAP", "🥿", "mdi:shoe-formal", "#D65A8E")),
            new VocabularyTerm("electro-swing-dance", "Electro Swing", ["Electro Swing Dance"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "swing-vernacular", ["family"] = "electro", ["parent"] = "swing", ["tempo_min"] = "110", ["tempo_max"] = "140", ["typical_genres"] = new object?[] { "Electro Swing" }, ["description"] = "An uncodified freestyle dance done to electro swing music, mixing Lindy Hop, solo jazz, hip-hop and shuffle dance, largely a YouTube and party-event phenomenon. Distinguished by having no formal basis and being mostly solo and performative; it is rarely danced at true swing socials (vs the codified vernacular swing dances)." },
                new TermDisplay("ES", "🎧", "material-symbols:headphones", "#6E8B9E"))
        ],
        grouping: new TermGrouping("family", [new("swing-partner", "Swing partner"), new("boogie-rocknroll", "Boogie & rock'n'roll"), new("solo-rhythmic", "Solo & rhythmic"), new("electro", "Electro")])), ReviewStatus.Unflagged);

    private static DancePack BuildBlues() => new(PackIds.Blues,
        "Blues", "Blues partner dances and the blues idioms (jookin' and ballroomin').",
        ["blues-partner", "blues-idiom"],
        new Dimension(SocialDanceVocabulary.DancesDimension, "pack",
        [
            new VocabularyTerm("blues-dancing", "Blues", ["Blues Dancing"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-partner", ["tempo_min"] = "50", ["tempo_max"] = "160", ["tempo_note"] = "Upper bound raised from 120 to 160 so fast blues (struttin', uptempo shuffles) is not excluded; per the consumer's dance-taxonomy research (2026-06-19), the scene dances fast blues at 120-160+ BPM. The idioms below carry no tempo: no blues-dance source gives them BPM figures.", ["typical_genres"] = new object?[] { "Chicago Blues", "Soul Blues", "Delta Blues", "Vocal Jazz" }, ["description"] = "A partner dance to blues music in close embrace built on improvisation and emotional expression, revived from the 2000s within the swing community out of African-American juke-joint traditions. Distinguished from Lindy Hop by being more intimate, slower and 'grounded' (bent knees, low center, body-to-body), with no fixed basic figure." },
                new TermDisplay("BLS", "🎸", "mdi:guitar-acoustic", "#C4B1FF")),
            new VocabularyTerm("slow-drag", "Slow Drag", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-partner", ["parent"] = "blues-dancing", ["tempo_min"] = "40", ["tempo_max"] = "70", ["typical_genres"] = new object?[] { "Delta Blues", "Soul Blues" }, ["description"] = "The oldest documented African-American blues partner dance: a very slow, intimate close embrace where partners 'drag' across the floor with minimal travel. Distinguished as the extreme-slow idiom (40-70 BPM) emphasizing body contact, shared breathing and micro-movements (vs general Blues Dancing, of which it is the slowest, most minimal form)." },
                new TermDisplay("SD", "🫂", "mdi:human-male-female", "#9887FE")),
            new VocabularyTerm("struttin", "Struttin'", ["Struttin"], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "Delta Blues", "Country Blues" }, ["description"] = "A jookin' blues idiom from the bars of Beale Street in Memphis (1930s-50s): partners in an inward-leaning close embrace step on every beat by default, each with independent, syncopated footwork. Distinguishing trait: compact, independent syncopated footwork in close embrace (vs. the travelling, rolling-torso Strut of New Orleans jazz-blues, a separate idiom this value does not cover)." },
                new TermDisplay("STT", "🎩", "mdi:shoe-formal", "#1E88E5")),
            new VocabularyTerm("savoy-walk", "Savoy Walk", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "Jazz Blues", "Classic Vaudeville Blues", "Barrelhouse Piano" }, ["description"] = "A ballroomin' blues idiom from the Savoy Ballroom, danced to slow jazz-blues: a close-embrace slow-quick two-step (slow-slow-quick-quick) broken up by flashy turns, lifts and dips timed to the melody rather than to the rhythm section. Distinguishing trait: an upright slow-quick walk with tricks on the melody (vs. the grounded jookin' idioms, such as Struttin', that hold a steady pulse in place)." },
                new TermDisplay("SVW", "🚶", "material-symbols:footprint", "#6ECCFA")),
            new VocabularyTerm("texas-shuffle", "Texas Shuffle", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "West Coast Blues" }, ["description"] = "A jookin' blues idiom danced to West Coast blues, the music Texas musicians made in California, where the dance itself originated despite its name: sliding, shuffling footwork over a subtle triple pulse, with stretch and compression and passes and turns along a slotted track. Distinguishing trait: a slotted track with stretch-and-pull passes (vs. Struttin', which stays in close embrace in place, and the explicit triple-step basic of Chicago Triple)." },
                new TermDisplay("TXS", "🤠", "mdi:shoe-print", "#96A0DD")),
            new VocabularyTerm("chicago-triple", "Chicago Triple", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "Chicago Blues" }, ["description"] = "A blues idiom created in Chicago to electric Chicago blues with a shuffle rhythm, built on a triple-step basic that dancers leave and return to, with stretch, compression and a swinging feel; suited to mid- and up-tempo tunes. Distinguishing trait: a triple step with stretch and compression to an electric band shuffle (vs. the relaxed, in-place triple of Piedmont Triple to acoustic fingerpicking)." },
                new TermDisplay("CHT", "🏙️", "mdi:guitar-electric", "#7B79C2")),
            new VocabularyTerm("piedmont-triple", "Piedmont Triple", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "Piedmont Blues" }, ["description"] = "A relaxed jookin' spot dance built on a near-constant shuffling triple, three foot movements in two beats kept under the hips, while the body stays in place and the partners move toward and away from each other through the upper body; danced to acoustic, ragtime-based, fingerpicked Piedmont blues. Distinguishing trait: stationary triple footwork to acoustic fingerpicking (vs. the stretch and compression of Chicago Triple to an electric band shuffle)." },
                new TermDisplay("PDT", "👣", "material-symbols:footprint", "#1785AF")),
            new VocabularyTerm("funky-butt", "Funky Butt", [], false,
                new Dictionary<string, object?>(System.StringComparer.Ordinal) { ["tradition"] = "blues-vernacular", ["family"] = "blues-idiom", ["parent"] = "blues-dancing", ["typical_genres"] = new object?[] { "Chicago Blues", "West Coast Blues", "Jump Blues", "Funk" }, ["description"] = "A jookin' blues idiom whose name is recorded as early as the late 19th century: the pelvis sways forward and back while stepping side to side, two beats per side, the hips extending back to counterbalance the partner and create compression and leverage; danced to funk-leaning blues. Distinguishing trait: pelvis-led counterbalance on a two-beat side-to-side step (vs. the footwork-led triples of Chicago Triple and Piedmont Triple)." },
                new TermDisplay("FKB", "🌀", "mdi:human-female-dance", "#649AF8"))
        ],
        grouping: new TermGrouping("family", [new("blues-partner", "Blues partner"), new("blues-idiom", "Blues idioms")])), ReviewStatus.Unflagged);

    private static DancePack BuildTango() => new(PackIds.Tango,
        "Tango (Argentine)", "Argentine tango social dances — tango de salón, vals, milonga, canyengue.",
        ["argentine"],
